local PlantSupportStakeMaker = {}
local PRODUCTS = {
    iron_plantsupportstake = { name = "Železni kolček za oporo rastlin", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni kolček za oporo rastlin za vrtnarje." },
    bronze_plantsupportstake = { name = "Bronast kolček za oporo rastlin", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast kolček za oporo rastlin za vrtnarje." },
    silver_plantsupportstake = { name = "Srebrn kolček za oporo rastlin", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn kolček za oporo rastlin za vrtnarje." },
    gilded_plantsupportstake = { name = "Pozlačen kolček za oporo rastlin", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen kolček za oporo rastlin za vrtnarje." },
    jewel_set_plantsupportstake = { name = "Draguljast kolček za oporo rastlin", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast kolček za oporo rastlin za vrtnarje." },
    royal_sovereign_plantsupportstake = { name = "Kraljevski suveren kolček za oporo rastlin", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren kolček za oporo rastlin z biseri za krono." },
}
local BUILDINGS = {
    plantsupportstake_workshop = { name = "Plantsupportstake delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    plantsupportstake_house = { name = "Plantsupportstake hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_plantsupportstake_atelier = { name = "Mojstrski plantsupportstake atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_plantsupportstake_palace = { name = "Suverena plantsupportstake palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PlantSupportStakeMaker.ironStock=14; PlantSupportStakeMaker.bronzeStock=12; PlantSupportStakeMaker.woodStock=16; PlantSupportStakeMaker.leatherStock=8; PlantSupportStakeMaker.silverStock=8; PlantSupportStakeMaker.goldStock=6; PlantSupportStakeMaker.jewelStock=4; PlantSupportStakeMaker.pearlStock=4
PlantSupportStakeMaker.productStock = {}; PlantSupportStakeMaker.buildings = {}; PlantSupportStakeMaker.maker = nil; PlantSupportStakeMaker.activeMaking = {}; PlantSupportStakeMaker.totalProducts = 0; PlantSupportStakeMaker.dayTimer = 0
function PlantSupportStakeMaker.init() PlantSupportStakeMaker.ironStock=14; PlantSupportStakeMaker.bronzeStock=12; PlantSupportStakeMaker.woodStock=16; PlantSupportStakeMaker.leatherStock=8; PlantSupportStakeMaker.silverStock=8; PlantSupportStakeMaker.goldStock=6; PlantSupportStakeMaker.jewelStock=4; PlantSupportStakeMaker.pearlStock=4; PlantSupportStakeMaker.productStock={}; PlantSupportStakeMaker.buildings={}; PlantSupportStakeMaker.maker=nil; PlantSupportStakeMaker.activeMaking={}; PlantSupportStakeMaker.totalProducts=0; PlantSupportStakeMaker.dayTimer=0; print("[PlantSupportStakeMaker] Royal Plant Support Stake Maker System initialized (6 products, 4 buildings)") end
function PlantSupportStakeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlantSupportStakeMaker.maker={name=n or ("Kolčkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kolčkar najet: %s (spretnost: %d)",PlantSupportStakeMaker.maker.name,s),"success") end; return true end
function PlantSupportStakeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlantSupportStakeMaker.build(id) local ok,e=PlantSupportStakeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlantSupportStakeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlantSupportStakeMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlantSupportStakeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlantSupportStakeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PlantSupportStakeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PlantSupportStakeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PlantSupportStakeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PlantSupportStakeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PlantSupportStakeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlantSupportStakeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlantSupportStakeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlantSupportStakeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlantSupportStakeMaker.buildings==0 then return false,"Potrebna kolčkarska delavnica" end; if not PlantSupportStakeMaker.maker then return false,"Potreben kolčkar" end; return true end
function PlantSupportStakeMaker.make(pt,qty) qty=qty or 1; local ok,e=PlantSupportStakeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PlantSupportStakeMaker.ironStock=PlantSupportStakeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PlantSupportStakeMaker.bronzeStock=PlantSupportStakeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PlantSupportStakeMaker.woodStock=PlantSupportStakeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PlantSupportStakeMaker.leatherStock=PlantSupportStakeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PlantSupportStakeMaker.silverStock=PlantSupportStakeMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlantSupportStakeMaker.goldStock=PlantSupportStakeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlantSupportStakeMaker.jewelStock=PlantSupportStakeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlantSupportStakeMaker.pearlStock=PlantSupportStakeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlantSupportStakeMaker.maker then t=math.max(1,t-math.floor(PlantSupportStakeMaker.maker.skill/13)) end; table.insert(PlantSupportStakeMaker.activeMaking,{id="plantsupportstake_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlantSupportStakeMaker.completeMaking(m) local q=1.0+(PlantSupportStakeMaker.getQualityBonus()/100); if PlantSupportStakeMaker.maker then q=q+(PlantSupportStakeMaker.maker.skill/140) end; q=math.min(2.5,q); PlantSupportStakeMaker.productStock[m.productType]=(PlantSupportStakeMaker.productStock[m.productType] or 0)+m.quantity; PlantSupportStakeMaker.totalProducts=PlantSupportStakeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlantSupportStakeMaker.maker then PlantSupportStakeMaker.maker.itemsMade=PlantSupportStakeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlantSupportStakeMaker.maker.skill=math.min(100,PlantSupportStakeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kolček izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plantsupportstake.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PlantSupportStakeMaker.update(dt) if not _G.state then return end; PlantSupportStakeMaker.dayTimer=PlantSupportStakeMaker.dayTimer+dt; if PlantSupportStakeMaker.dayTimer>=30 then PlantSupportStakeMaker.dayTimer=0; for i=#PlantSupportStakeMaker.activeMaking,1,-1 do local m=PlantSupportStakeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlantSupportStakeMaker.completeMaking(m); table.remove(PlantSupportStakeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlantSupportStakeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlantSupportStakeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlantSupportStakeMaker.getStats() return {ironStock=PlantSupportStakeMaker.ironStock,bronzeStock=PlantSupportStakeMaker.bronzeStock,woodStock=PlantSupportStakeMaker.woodStock,leatherStock=PlantSupportStakeMaker.leatherStock,silverStock=PlantSupportStakeMaker.silverStock,goldStock=PlantSupportStakeMaker.goldStock,jewelStock=PlantSupportStakeMaker.jewelStock,pearlStock=PlantSupportStakeMaker.pearlStock,productStock=PlantSupportStakeMaker.productStock,numBuildings=#PlantSupportStakeMaker.buildings,hasMaker=PlantSupportStakeMaker.maker~=nil,makerName=PlantSupportStakeMaker.maker and PlantSupportStakeMaker.maker.name or "—",makerSkill=PlantSupportStakeMaker.maker and PlantSupportStakeMaker.maker.skill or 0,activeMaking=#PlantSupportStakeMaker.activeMaking,totalProducts=PlantSupportStakeMaker.totalProducts} end
return PlantSupportStakeMaker
